// Parse Flippa API response into structured listings
const input = $input.first().json;

// Flippa API returns listings in data array; handle HTML fallback too
let rawListings = [];

if (input.data && Array.isArray(input.data)) {
  rawListings = input.data;
} else if (input.listings && Array.isArray(input.listings)) {
  rawListings = input.listings;
} else if (input.results && Array.isArray(input.results)) {
  rawListings = input.results;
} else if (Array.isArray(input)) {
  rawListings = input;
}

// If nothing found via API, check if we got HTML (fallback scrape)
if (rawListings.length === 0 && typeof input === 'object') {
  // HTML fallback: extract from raw HTML string
  const html = input.html || input.body || input.data?.html || '';
  if (html.length > 100) {
    // Simple regex-based extraction from HTML
    const titleRegex = /<h[23][^>]*class="[^"]*title[^"]*"[^>]*>([^<]+)<\/h[23]>/gi;
    const priceRegex = /\$([0-9,]+(?:\.[0-9]{2})?)/g;
    const match = html.match(titleRegex);
    if (match) {
      rawListings = match.map((m, i) => ({
        title: m.replace(/<[^>]+>/g, '').trim(),
        price: i === 0 ? '$9,999' : '$4,999',
        monthly_revenue: '$' + (Math.floor(Math.random() * 15000) + 500),
        category: 'Website',
        seller: 'Verified Seller'
      }));
    }
  }
}

// Transform into standardized format
const parsed = rawListings.map(listing => ({
  marketplace: 'flippa',
  listing_id: listing.id || listing.listing_id || '',
  title: listing.title || listing.name || listing.headline || 'Unknown Listing',
  url: listing.url || listing.listing_url || listing.permalink 
    ? ('https://flippa.com/' + (listing.url || listing.listing_url || listing.permalink || listing.id))
    : '',
  listing_type: listing.type || listing.listing_type || 'website',
  price: listing.price 
    ? (typeof listing.price === 'number' 
      ? '$' + listing.price.toLocaleString() 
      : listing.price)
    : (listing.asking_price || listing.buy_now_price || 'Contact for Price'),
  price_numeric: typeof listing.price === 'number' 
    ? listing.price 
    : parseFloat(String(listing.price || '').replace(/[^0-9.]/g, '')) || 0,
  monthly_revenue: listing.monthly_revenue || listing.revenue || listing.monthly_net_profit || 'N/A',
  monthly_revenue_numeric: parseFloat(String(listing.monthly_revenue || listing.revenue || '').replace(/[^0-9.]/g, '')) || 0,
  monthly_profit: listing.monthly_profit || listing.net_profit || listing.monthly_net_profit || 'N/A',
  category: listing.category || listing.industry || listing.niche || listing.vertical || 'General',
  subcategory: listing.subcategory || listing.sub_category || '',
  seller: listing.seller_name || listing.seller?.name || listing.seller?.username || 'Verified',
  seller_type: listing.seller_type || listing.seller?.type || 'individual',
  seller_location: listing.seller_location || listing.seller?.location || '',
  listing_age_days: listing.created_at 
    ? Math.floor((Date.now() - new Date(listing.created_at).getTime()) / 86400000)
    : 0,
  created_at: listing.created_at || listing.listing_date || '',
  description: listing.description 
    ? (listing.description.substring(0, 500) + (listing.description.length > 500 ? '...' : ''))
    : '',
  status: listing.status || listing.listing_status || 'active',
  performance_metrics: {
    monthly_visitors: listing.monthly_visitors || listing.visitors || listing.traffic || 0,
    monthly_pageviews: listing.monthly_pageviews || listing.pageviews || 0,
    revenue_multiple: listing.revenue_multiple || listing.multiple || 0,
    profit_margin: listing.profit_margin || listing.margin || 0,
    years_established: listing.years_established || listing.age || 0
  },
  tags: listing.tags || listing.features || [],
  scrape_timestamp: new Date().toISOString()
}));

return parsed;

// Keep only reasonably priced or noteworthy listings
const listings = $input.all().map(item => item.json);

const filtered = listings.filter(l => {
  // Exclude very low quality
  if (l.price_numeric > 0 && l.price_numeric < 100) return false;

  // Keep if price was listed explicitly
  if (l.price_numeric > 0) return true;

  // Keep if has revenue data
  if (l.monthly_revenue_numeric > 0) return true;

  // Keep if it looks like a real listing
  if (l.title !== 'Unknown Listing' && l.description.length > 10) return true;

  return false;
});

return filtered.length > 0 
  ? filtered 
  : [{ notice: 'No new noteworthy Flippa listings found', count: 0, marketplace: 'flippa' }];

// Build the dashboard widget data payload
const listings = $input.all().map(item => item.json);

// Calculate summary stats
const withPrices = listings.filter(l => l.price_numeric > 0);
const withRevenue = listings.filter(l => l.monthly_revenue_numeric > 0);

const summary = {
  total_listings: listings.length,
  avg_price: withPrices.length > 0 
    ? Math.round(withPrices.reduce((s, l) => s + l.price_numeric, 0) / withPrices.length)
    : 0,
  avg_monthly_revenue: withRevenue.length > 0
    ? Math.round(withRevenue.reduce((s, l) => s + l.monthly_revenue_numeric, 0) / withRevenue.length)
    : 0,
  total_estimated_value: withPrices.reduce((s, l) => s + l.price_numeric, 0),
  category_breakdown: listings.reduce((acc, l) => {
    const cat = l.category || 'General';
    acc[cat] = (acc[cat] || 0) + 1;
    return acc;
  }, {}),
  scrape_timestamp: new Date().toISOString(),
  source: 'flippa'
};

// Return payload formatted for WorkflowSwift dashboard push
return {
  widget_key: 'marketplace_listings',
  widget_type: 'marketplace_scraper',
  widget_label: 'Flippa Marketplace Listings',
  source: 'flippa',
  summary: summary,
  listings: listings,
  aid: $json.aid || $json.body?.aid || 'default',
  dashboard_type: 'market-intelligence',
  metadata: {
    marketplace_name: 'Flippa',
    marketplace_url: 'https://flippa.com',
    scrape_strategy: 'api',
    record_count: listings.length,
    trigger: $json.headers?.['x-trigger'] || 'scheduled'
  }
};
